40	const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get("window");
41	
42	const OLDER_EDGE_KEY = "__older_edge__";
43	
44	type ViewerPage =
45	  | { kind: "event"; event: EventTimelineItem }
