52	export const MediaViewerModalContent: FC<Props> = ({ payload }) => {
53	  const [, setPayload] = useAtom(TimelineAtoms.mediaViewerPayload);
54	  const setImageInfoPayload = useSetAtom(TimelineAtoms.imageInfoPayload);
55	  const setVideoInfoPayload = useSetAtom(TimelineAtoms.videoInfoPayload);
56	  const listRef = useRef<FlatList<ViewerPage>>(null);
57	  const [showControls, setShowControls] = useState(true);
58	  const [currentIndex, setCurrentIndex] = useState(0);
59	  const localUriByEventIdRef = useRef<Map<string, string | null>>(new Map());
60	
61	  const room = useMemo<RoomInterface | undefined>(() => {
62	    try {
63	      return MatrixCore.getRoom(payload.roomId);
64	    } catch {
65	      return undefined;
66	    }
67	  }, [payload.roomId]);
68	
69	  const { mediaItems, loading, loadMore, reachedStart } = useMediaTimeline({
70	    room,
71	    roomId: payload.roomId,
72	  });
73	
74	  /** Filtered events sorted newest-first. */
75	  const events = useMemo<EventTimelineItem[]>(() => {
76	    const filtered = mediaItems.filter((item) => getMediaKind(item) !== null);
77	    return filtered.length === 0 ? [payload.initialEvent] : filtered;
78	  }, [mediaItems, payload.initialEvent]);
79	
80	  /** FlashList data: events + the older-edge sentinel when more history
81	  remains. Sentinel is a trailing "loading" page: swiping into it triggers
82	  `loadMore`, and when new events arrive they're inserted between the last
83	  real event and the sentinel, so the user slides from the spinner straight
84	  onto the newest item of the just-loaded batch. We suppress the sentinel
85	  while the hook's initial pagination is still in flight so the seeded
86	  single-item render can't accidentally land on it. */
87	  const pages = useMemo<ViewerPage[]>(() => {
88	    const result: ViewerPage[] = events.map((event) => ({
89	      kind: "event",
90	      event,
91	    }));
92	    if (!loading && !reachedStart) {
93	      result.push({ kind: "older-edge" });
94	    }
95	    return result;
96	  }, [events, loading, reachedStart]);
97	
98	  /** Pages-index for the tapped event — resolved against the hydrated list. */
99	  const initialPageIndex = useMemo(() => {
100	    const eventIdx = events.findIndex(
101	      (event) => getEventId(event) === payload.initialEventId,
102	    );
103	    return eventIdx >= 0 ? eventIdx : 0;
104	  }, [events, payload.initialEventId]);
105	
106	  // Sync `currentIndex` with `initialPageIndex` until the list mounts against
107	  // the hydrated data — otherwise the header reads from pages[0] (wrong
108	  // event) while the seeded-single-item pass is still on screen.
109	  const syncedIndexRef = useRef(false);
110	  useEffect(() => {
111	    if (loading) return;
112	    if (syncedIndexRef.current) return;
