114	    setCurrentIndex(initialPageIndex);
115	  }, [loading, initialPageIndex]);
116	
117	  const currentPage = pages[currentIndex];
118	  const currentEvent =
119	    currentPage?.kind === "event"
120	      ? currentPage.event
121	      : loading
122	        ? payload.initialEvent
123	        : null;
124	  const currentKind = currentEvent ? getMediaKind(currentEvent) : null;
125	
126	  // If `reachedStart` flips while the user is on the older-edge sentinel, the
127	  // sentinel disappears from `pages` and the current index points past the
128	  // end. Snap back to the last real event so the viewer isn't blank.
129	  useEffect(() => {
130	    if (!reachedStart) return;
131	    if (currentIndex < events.length) return;
132	    const targetIndex = Math.max(0, events.length - 1);
133	    listRef.current?.scrollToIndex({ index: targetIndex, animated: false });
134	    setCurrentIndex(targetIndex);
135	  }, [reachedStart, events.length, currentIndex]);
136	
137	  const senderName = useMemo(() => {
138	    if (!currentEvent) return null;
139	    if (currentEvent.senderProfile.tag === ProfileDetails_Tags.Ready) {
140	      return (
141	        currentEvent.senderProfile.inner.displayName ?? currentEvent.sender
142	      );
143	    }
144	    return currentEvent.sender;
145	  }, [currentEvent]);
146	
147	  const formattedDate = useMemo(() => {
148	    if (!currentEvent) return null;
149	    return format(Number(currentEvent.timestamp), "MMM d, HH:mm");
150	  }, [currentEvent]);
151	
152	  const controlsAnimation = useRef(
153	    animateParallel(
154	      { translateY: [-120, 0], opacity: [0, 1] },
155	      { duration: 280 },
156	    ),
157	  ).current;
158	
159	  useEffect(() => {
160	    if (showControls) controlsAnimation.start();
161	    else controlsAnimation.reverse();
162	  }, [showControls]);
163	
164	  const onClose = useCallback(() => {
165	    setPayload(null);
166	  }, [setPayload]);
167	
168	  const handleSingleTap = useCallback(() => {
169	    setShowControls((prev) => !prev);
170	  }, []);
171	
172	  const handleViewableItemsChanged = useCallback(
173	    ({ viewableItems }: { viewableItems: { index: number | null }[] }) => {
174	      const first = viewableItems[0];
175	      if (first?.index == null) return;
176	      setCurrentIndex(first.index);
177	    },
178	    [],
179	  );
180	
181	  // Paginate once the user lands on the older-edge sentinel. The hook's
182	  // internal guards (isPaginatingRef / reachedStartRef) stop duplicate calls.
183	  useEffect(() => {
184	    if (currentPage?.kind === "older-edge") loadMore();
185	  }, [currentPage, loadMore]);
186	
187	  const handleLocalUriChange = useCallback(
188	    (eventId: string | null, uri: string | null) => {
189	      if (!eventId) return;
190	      localUriByEventIdRef.current.set(eventId, uri);
191	    },
192	    [],
193	  );
194	
195	  const handleOpenInfo = useCallback(() => {
196	    if (!currentEvent) return;
197	    const eventId = getEventId(currentEvent);
198	    const localUri = eventId
199	      ? (localUriByEventIdRef.current.get(eventId) ?? null)
200	      : null;
201	    if (currentKind === "image") {
202	      setImageInfoPayload({
203	        event: currentEvent,
204	        roomId: payload.roomId,
205	        localUri,
206	      });
207	    } else if (currentKind === "video") {
208	      setVideoInfoPayload({
209	        event: currentEvent,
210	        roomId: payload.roomId,
211	        localUri,
212	      });
213	    }
214	  }, [
215	    currentEvent,
216	    currentKind,
217	    payload.roomId,
218	    setImageInfoPayload,
219	    setVideoInfoPayload,
220	  ]);
221	
222	  const keyExtractor = useCallback((page: ViewerPage) => {
223	    if (page.kind === "older-edge") return OLDER_EDGE_KEY;
224	    return getEventId(page.event) ?? "";
225	  }, []);
226	
227	  const renderItem = useCallback(
228	    ({ item, index }: { item: ViewerPage; index: number }) => {
229	      if (item.kind === "older-edge") {
230	        return <MediaEdgePage />;
231	      }
232	      const event = item.event;
233	      const kind = getMediaKind(event);
234	      const eventId = getEventId(event);
235	      const onUriChange = (uri: string | null) =>
236	        handleLocalUriChange(eventId, uri);
237	      return (
238	        <View style={styles.page}>
239	          {kind === "image" ? (
240	            <MediaImagePage
241	              event={event}
242	              onSingleTap={handleSingleTap}
243	              onLocalUriChange={onUriChange}
244	            />
245	          ) : kind === "video" ? (
246	            <MediaVideoPage
247	              event={event}
248	              isActive={index === currentIndex}
249	              onSingleTap={handleSingleTap}
250	              onLocalUriChange={onUriChange}
251	            />
252	          ) : null}
253	        </View>
254	      );
255	    },
256	    [currentIndex, handleSingleTap, handleLocalUriChange],
257	  );
258	
259	  const getItemLayout = useCallback(
260	    (_: ArrayLike<ViewerPage> | null | undefined, index: number) => ({
261	      length: SCREEN_WIDTH,
262	      offset: SCREEN_WIDTH * index,
263	      index,
264	    }),
265	    [],
266	  );
267	
268	  return (
269	    <Modal
270	      visible
271	      animationType="fade"
272	      statusBarTranslucent
273	      transparent
274	      onRequestClose={onClose}
275	    >
276	      <BottomSheetModalProvider>
277	        <Block background={Colors.black} flex={1}>
278	          <FlatList
279	            // Remount when the hook's initial pagination completes so that
280	            // `initialScrollIndex` is re-evaluated against the hydrated list
281	            // and lands on the tapped event's real index. `initialScrollIndex`
282	            // is applied only once at mount, so without this remount the list
283	            // stays anchored to the seeded single-item position.
284	            key={loading ? "loading" : "hydrated"}
285	            ref={listRef}
286	            data={pages}
287	            renderItem={renderItem}
288	            keyExtractor={keyExtractor}
289	            getItemLayout={getItemLayout}
290	            horizontal
291	            inverted
292	            pagingEnabled
293	            showsHorizontalScrollIndicator={false}
294	            initialScrollIndex={initialPageIndex}
295	            onViewableItemsChanged={handleViewableItemsChanged}
296	          />
297	
298	          <Block
299	            absolute
300	            offsets={{ top: 0, left: 0, right: 0 }}
301	            zIndex={10}
302	            paddings={[56, 20, 16, 20]}
303	            flexDirection="row"
304	            align="center"
305	            justify="space-between"
306	            gap={12}
307	            background={Colors.primary}
308	            animations={controlsAnimation.animations}
309	            pointerEvents={showControls ? "auto" : "none"}
310	          >
311	            <BlurGradientOverlay />
312	            <Block width={60} align="flex-start" zIndex={2}>
313	              {!!currentEvent && (
314	                <Button.Wrapper onPress={handleOpenInfo}>
315	                  <Image
316	                    source={require("assets/icons/info.png")}
317	                    style={styles.infoIcon}
318	                    tintColor={Colors.white}
319	                  />
320	                </Button.Wrapper>
321	              )}
322	            </Block>
323	            <Block flex={1} align="center" gap={2} zIndex={2}>
324	              {senderName && (
325	                <Text
326	                  color={Colors.white}
327	                  font="InstrumentSans-Semibold"
328	                  numberOfLines={1}
329	                >
330	                  {senderName}
331	                </Text>
332	              )}
333	              {formattedDate && (
334	                <Text
335	                  size={TextSize.tiny}
336	                  color={Colors.white80}
337	                  numberOfLines={1}
338	                >
339	                  {formattedDate}
340	                </Text>
341	              )}
342	            </Block>
343	            <Block width={60} align="flex-end" zIndex={2}>
344	              <Button.Wrapper onPress={onClose}>
345	                <Text font="InstrumentSans-Semibold" color={Colors.white}>
346	                  Close
347	                </Text>
348	              </Button.Wrapper>
349	            </Block>
350	          </Block>
351	        </Block>
352	        <ImageInfoBottomSheet />
353	        <VideoInfoBottomSheet />
354	      </BottomSheetModalProvider>
355	    </Modal>
356	  );
357	};
358	
359	const styles = StyleSheet.create({
360	  page: {
361	    width: SCREEN_WIDTH,
362	    height: SCREEN_HEIGHT,
363	  },
364	  infoIcon: {
365	    width: 24,
366	    height: 24,
367	  },
368	});
