const currentIndexRef = useRef(currentIndex);
const dataLengthRef = useRef(0);
useEffect(() => {
  currentIndexRef.current = currentIndex;
}, [currentIndex]);

const room = useMemo<RoomInterface | undefined>(() => {
  try {
    return MatrixCore.getRoom(payload.roomId);
  } catch {
    return undefined;
  }
}, [payload.roomId]);

const { mediaItems, loading, loadMore, reachedStart } = useMediaTimeline({
  room,
  roomId: payload.roomId,
});

const events = useMemo<EventTimelineItem[]>(() => {
  const filtered = mediaItems.filter((item) => getMediaKind(item) !== null);
  return filtered.length === 0 ? [payload.initialEvent] : filtered;
}, [mediaItems, payload.initialEvent]);

const initialPageIndex = useMemo(() => {
  const idx = events.findIndex(
    (event) => getEventId(event) === payload.initialEventId,
  );
  return idx >= 0 ? idx : 0;
}, [events, payload.initialEventId]);

// Grow the allocation after each batch so new null slots appear at the end
// while the batch is filling the previous ones — size stays stable mid-batch.
const [allocationSize, setAllocationSize] = useState(0);
useEffect(() => {
  if (loading || reachedStart) return;
  setAllocationSize((prev) => Math.max(prev, events.length + PRELOAD_SLOTS));
