// null items render as a loading spinner; they are updated in-place when
// events arrive because the index (and therefore the view) never moves.
const data = useMemo<(EventTimelineItem | null)[]>(() => {
  if (reachedStart) return events;
  const nullCount = Math.max(0, allocationSize - events.length);
  return [...events, ...Array<null>(nullCount).fill(null)];
}, [events, reachedStart, allocationSize]);

useEffect(() => {
  dataLengthRef.current = data.length;
}, [data.length]);

