import { BottomSheetModalProvider } from "@gorhom/bottom-sheet";
import { animateParallel, Block, Text } from "@prototyp/skeletor";
import {
  type EventTimelineItem,
  ProfileDetails_Tags,
  type RoomInterface,
} from "@unomed/react-native-matrix-sdk";
import { format } from "date-fns";
import { useAtom, useSetAtom } from "jotai";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { getEventId } from "modules/matrix-client/utils";
import { TimelineAtoms } from "modules/timeline/jotai";
import {
  type FC,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  Dimensions,
  FlatList,
  Image,
  Modal,
  StyleSheet,
  View,
  type ViewToken,
} from "react-native";
import { useMediaTimeline } from "screens/room-media/hooks";
import { ImageInfoBottomSheet } from "screens/room/fragments/image-info-bottom-sheet";
import { VideoInfoBottomSheet } from "screens/room/fragments/video-info-bottom-sheet";
import { Colors, TextSize } from "shared/styles";
import { BlurGradientOverlay } from "../blur-gradient-overlay";
import { Button } from "../button";
import { MediaEdgePage } from "./MediaEdgePage";
import { MediaImagePage } from "./MediaImagePage";
import { MediaVideoPage } from "./MediaVideoPage";
import { getMediaKind } from "./utils";

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get("window");

interface Props {
  payload: MediaViewerPayload;
}

export const MediaViewerModalContent: FC<Props> = ({ payload }) => {
  const [, setPayload] = useAtom(TimelineAtoms.mediaViewerPayload);
  const setImageInfoPayload = useSetAtom(TimelineAtoms.imageInfoPayload);
  const setVideoInfoPayload = useSetAtom(TimelineAtoms.videoInfoPayload);
  const flatListRef = useRef<FlatList<EventTimelineItem | null>>(null);
  const [showControls, setShowControls] = useState(true);
  const [currentIndex, setCurrentIndex] = useState(0);
  const currentIndexRef = useRef(0);
  const localUriByEventIdRef = useRef<Map<string, string | null>>(new Map());

  const room = useMemo<RoomInterface | undefined>(() => {
    try {
      return MatrixCore.getRoom(payload.roomId);
    } catch {
      return undefined;
    }
  }, [payload.roomId]);

  const { mediaItems, loading, loadMore, reachedStart } = useMediaTimeline({
    room,
    roomId: payload.roomId,
  });

  const events = useMemo<EventTimelineItem[]>(() => {
    const filtered = mediaItems.filter((item) => getMediaKind(item) !== null);
    return filtered.length === 0 ? [payload.initialEvent] : filtered;
  }, [mediaItems, payload.initialEvent]);

  const initialPageIndex = useMemo(() => {
    const idx = events.findIndex(
      (event) => getEventId(event) === payload.initialEventId,
    );
    return idx >= 0 ? idx : 0;
  }, [events, payload.initialEventId]);

  // data = real events + null loading placeholder at the end (older side).
  const data = useMemo<(EventTimelineItem | null)[]>(() => {
    if (reachedStart) return events;
    return [...events, null];
  }, [events, reachedStart]);

  // Scroll to the tapped event once the initial batch is ready.
  const syncedRef = useRef(false);
  useEffect(() => {
    if (loading || syncedRef.current) return;
    syncedRef.current = true;
    if (initialPageIndex > 0) {
      flatListRef.current?.scrollToIndex({ index: initialPageIndex, animated: false });
    }
    currentIndexRef.current = initialPageIndex;
    setCurrentIndex(initialPageIndex);
  }, [loading, initialPageIndex]);

  // When new items arrive and the user is sitting on/past the loading slot,
  // jump them to the first newly loaded event.
  const prevEventsLengthRef = useRef(0);
  useEffect(() => {
    if (loading) return;
    const prevLen = prevEventsLengthRef.current;
    prevEventsLengthRef.current = events.length;
    if (events.length > prevLen && prevLen > 0 && currentIndexRef.current >= prevLen) {
      flatListRef.current?.scrollToIndex({ index: prevLen, animated: false });
      currentIndexRef.current = prevLen;
      setCurrentIndex(prevLen);
    }
  }, [events.length, loading]);

  // Trigger loadMore when the user reaches the null loading slot.
  useEffect(() => {
    if (currentIndex >= events.length && !loading && !reachedStart) {
      loadMore();
    }
  }, [currentIndex, events.length, loading, reachedStart, loadMore]);

  const currentEvent = useMemo<EventTimelineItem | null>(() => {
    const item = data[currentIndex];
    if (item != null) return item as EventTimelineItem;
    return loading ? payload.initialEvent : null;
  }, [data, currentIndex, loading, payload.initialEvent]);

  const currentKind = currentEvent ? getMediaKind(currentEvent) : null;

  const senderName = useMemo(() => {
    if (!currentEvent) return null;
    if (currentEvent.senderProfile.tag === ProfileDetails_Tags.Ready) {
      return currentEvent.senderProfile.inner.displayName ?? currentEvent.sender;
    }
    return currentEvent.sender;
  }, [currentEvent]);

  const formattedDate = useMemo(() => {
    if (!currentEvent) return null;
    return format(Number(currentEvent.timestamp), "MMM d, HH:mm");
  }, [currentEvent]);

  const controlsAnimation = useRef(
    animateParallel(
      { translateY: [-120, 0], opacity: [0, 1] },
      { duration: 280 },
    ),
  ).current;

  useEffect(() => {
    if (showControls) controlsAnimation.start();
    else controlsAnimation.reverse();
  }, [showControls]);

  const onClose = useCallback(() => setPayload(null), [setPayload]);

  const handleSingleTap = useCallback(() => {
    setShowControls((prev) => !prev);
  }, []);

  const handleLocalUriChange = useCallback(
    (eventId: string | null, uri: string | null) => {
      if (!eventId) return;
      localUriByEventIdRef.current.set(eventId, uri);
    },
    [],
  );

  const handleOpenInfo = useCallback(() => {
    if (!currentEvent) return;
    const eventId = getEventId(currentEvent);
    const localUri = eventId
      ? (localUriByEventIdRef.current.get(eventId) ?? null)
      : null;
    if (currentKind === "image") {
      setImageInfoPayload({ event: currentEvent, roomId: payload.roomId, localUri });
    } else if (currentKind === "video") {
      setVideoInfoPayload({ event: currentEvent, roomId: payload.roomId, localUri });
    }
  }, [currentEvent, currentKind, payload.roomId, setImageInfoPayload, setVideoInfoPayload]);

  // Stable callback — only accesses refs and stable setters, no stale closure risk.
  const onViewableItemsChanged = useRef(
    ({ viewableItems }: { viewableItems: ViewToken[] }) => {
      if (!viewableItems.length || viewableItems[0].index == null) return;
      const idx = viewableItems[0].index;
      currentIndexRef.current = idx;
      setCurrentIndex(idx);
    },
  ).current;

  const viewabilityConfig = useRef({ itemVisiblePercentThreshold: 90 }).current;

  const keyExtractor = useCallback(
    (item: EventTimelineItem | null, index: number) => {
      if (item === null) return "__loading__";
      return getEventId(item) ?? String(index);
    },
    [],
  );

  const renderItem = useCallback(
    ({ item, index }: { item: EventTimelineItem | null; index: number }) => {
      if (item === null) {
        return <MediaEdgePage />;
      }
      const kind = getMediaKind(item);
      const eventId = getEventId(item);
      return (
        <View style={styles.page}>
          {kind === "image" ? (
            <MediaImagePage
              event={item}
              onSingleTap={handleSingleTap}
              onLocalUriChange={(uri) => handleLocalUriChange(eventId, uri)}
            />
          ) : kind === "video" ? (
            <MediaVideoPage
              event={item}
              isActive={index === currentIndex}
              onSingleTap={handleSingleTap}
              onLocalUriChange={(uri) => handleLocalUriChange(eventId, uri)}
            />
          ) : null}
        </View>
      );
    },
    [handleSingleTap, handleLocalUriChange, currentIndex],
  );

  return (
    <Modal
      visible
      animationType="fade"
      statusBarTranslucent
      transparent
      onRequestClose={onClose}
    >
      <BottomSheetModalProvider>
        <Block background={Colors.black} flex={1}>
          <FlatList
            ref={flatListRef}
            data={data}
            keyExtractor={keyExtractor}
            renderItem={renderItem}
            horizontal
            inverted
            pagingEnabled
            showsHorizontalScrollIndicator={false}
            onViewableItemsChanged={onViewableItemsChanged}
            viewabilityConfig={viewabilityConfig}
            extraData={currentIndex}
            onScrollToIndexFailed={({ index }) => {
              setTimeout(() => {
                flatListRef.current?.scrollToIndex({ index, animated: false });
              }, 100);
            }}
          />

          <Block
            absolute
            offsets={{ top: 0, left: 0, right: 0 }}
            zIndex={10}
            paddings={[56, 20, 16, 20]}
            flexDirection="row"
            align="center"
            justify="space-between"
            gap={12}
            background={Colors.primary}
            animations={controlsAnimation.animations}
            pointerEvents={showControls ? "auto" : "none"}
          >
            <BlurGradientOverlay />
            <Block width={60} align="flex-start" zIndex={2}>
              {!!currentEvent && (
                <Button.Wrapper onPress={handleOpenInfo}>
                  <Image
                    source={require("assets/icons/info.png")}
                    style={styles.infoIcon}
                    tintColor={Colors.white}
                  />
                </Button.Wrapper>
              )}
            </Block>
            <Block flex={1} align="center" gap={2} zIndex={2}>
              {senderName && (
                <Text
                  color={Colors.white}
                  font="InstrumentSans-Semibold"
                  numberOfLines={1}
                >
                  {senderName}
                </Text>
              )}
              {formattedDate && (
                <Text
                  size={TextSize.tiny}
                  color={Colors.white80}
                  numberOfLines={1}
                >
                  {formattedDate}
                </Text>
              )}
            </Block>
            <Block width={60} align="flex-end" zIndex={2}>
              <Button.Wrapper onPress={onClose}>
                <Text font="InstrumentSans-Semibold" color={Colors.white}>
                  Close
                </Text>
              </Button.Wrapper>
            </Block>
          </Block>
        </Block>
        <ImageInfoBottomSheet />
        <VideoInfoBottomSheet />
      </BottomSheetModalProvider>
    </Modal>
  );
};

const styles = StyleSheet.create({
  page: {
    width: SCREEN_WIDTH,
    height: SCREEN_HEIGHT,
  },
  infoIcon: {
    width: 24,
    height: 24,
  },
});

