// Keep a ref so effects that run on events.length don't need currentIndex as a dep.
const currentIndexRef = useRef(currentIndex);
useEffect(() => {
  currentIndexRef.current = currentIndex;
}, [currentIndex]);

// Sync `currentIndex` with `initialPageIndex` until the list mounts against
// the hydrated data — otherwise the header reads from pages[0] (wrong
// event) while the seeded-single-item pass is still on screen.
const syncedIndexRef = useRef(false);
useEffect(() => {
  console.log("[MediaViewer] sync effect", { loading, synced: syncedIndexRef.current, initialPageIndex });
  if (loading) return;
  if (syncedIndexRef.current) return;
  syncedIndexRef.current = true;
  console.log("[MediaViewer] syncing currentIndex to", initialPageIndex);
  setCurrentIndex(initialPageIndex);
}, [loading, initialPageIndex]);

// When new events arrive while the user is on the older-edge sentinel,
// scroll to the first new event (index = prevEventsLength) so the spinner
// gives way to real content instead of staying stuck.
const prevEventsLengthRef = useRef(0);
useEffect(() => {
  if (loading) return;
  const prevLen = prevEventsLengthRef.current;
  prevEventsLengthRef.current = events.length;
  if (events.length > prevLen && prevLen > 0 && currentIndexRef.current >= prevLen) {
    console.log("[MediaViewer] auto-advance after loadMore", { prevLen, newLen: events.length, scrollTo: prevLen });
    listRef.current?.scrollToIndex({ index: prevLen, animated: false });
    setCurrentIndex(prevLen);
  }
}, [events.length, loading]);

